```javascript
async function safeFetch(url, options = {}) {
  try {
    const res = await fetch(url, options);

    if (!res.ok) {
      const err = await res.json();
      throw new Error(err._____ ?? 'HTTP ${res.status}');
    }

    return await res.json();
  } catch (e) {
    console.error("API 오류:", e.message);
    throw e;
  }
}
```

