class HTTPException(Exception):
    def __init__(self, status_code, detail):
        self.status_code = status_code
        self.detail = detail

memos = [{"id": 1, "title": "학습"}]

def get_memo(memo_id):
    memo = next((m for m in memos if m["id"] == memo_id), None)
    if not memo:
        raise HTTPException(status_code=404, detail="메모 없음")
    return memo

try:
    get_memo(99)
except HTTPException as e:
    print(e.status_code)
    print(e.detail)

class Turn:
    def __init__(self, role, content):
        self.role = role
        self.content = content

    def dict(self):
        return {"role": self.role, "content": self.content}

messages = [Turn("user", "안녕하세요")]
messages.append(Turn("assistant", "안녕하세요! 무엇을 도와드릴까요?"))
messages.append(Turn("user", "FastAPI 알려줘"))

print(len(messages))
print(messages[0].dict())

def call_claude(messages):
    if not messages:
        raise ValueError("메시지가 비어 있습니다.")
    return "응답: " + messages[-1]["content"]

msgs = [{"role": "user", "content": "Python이란?"}]
