class APIRouter:
    def __init__(self, prefix="", tags=None):
        self.prefix = prefix
        self.tags = tags or []
        self.routes = []

    def get(self, path):
        def decorator(func):
            self.routes.append({"method": "GET", "path": self.prefix + path})
            return func
        return decorator

class FastAPI:
    def __init__(self):
        self.routes = []

    def include_router(self, router):
        self.routes.extend(router.routes)

memo_router = APIRouter(prefix="/memos", tags=["memos"])

